package com.nextrade.persistence.adapter; import com.nextrade.common.event.*; import com.nextrade.service.ports.EventOutbox; import java.util.*; public final class OutboxRepositoryAdapter implements EventOutbox {private final List<DomainEvent> events=Collections.synchronizedList(new ArrayList<>());public void append(DomainEvent event){events.add(event);}public List<DomainEvent> snapshot(){synchronized(events){return List.copyOf(events);}}}
